 body+='<section class="wrap two-column section"><div><p class="eyebrow">BUILT AROUND YOUR WORLD</p><h2>'+h+'</h2><p>'+sol+'</p><h3>Make your quote request count.</h3><p>'+q+'</p></div><div><h3>Priorities to plan around</h3><ul class="bullets">'+''.join('<li>'+x+'</li>' for x in pts.split('|'))+'</ul>'+button('GET A QUOTE')+'</div></section>'
