REGIONS=[
('ontario','Ontario',['Toronto','Ottawa','Hamilton','Mississauga','Brampton','London','Kitchener','Waterloo','Cambridge','Windsor','Barrie','Oshawa','Kingston','Guelph','St. Catharines','Niagara Falls'],'From a single urban property to a portfolio spread across several cities, separate product deliveries from the on-site work required at each address.','For downtown and shared commercial sites, identify loading arrangements, work windows and the person who can authorize access. A multi-city request should include a separate contact and pole count for each property.'),
('quebec','Quebec',['Montreal','Quebec City'],'Describe the flag display, the site and your organization’s language and artwork requirements in the same request.','For municipal, institutional and event displays, identify the approved flag arrangement and applicable organizational guidance. Supply approved French artwork rather than relying on a translation of an existing design.'),
('british-columbia','British Columbia',['Vancouver','Surrey','Victoria','Kelowna'],'Delivery to a mainland property, an island destination or an interior event can involve different transport and scheduling needs.','Include the precise destination and any ferry, loading or site-access constraints. Describe outdoor exposure and the proposed surface for temporary poles so the display can be reviewed for the actual setting.'),
('alberta','Alberta',['Calgary','Edmonton'],'Plan flag displays around the site’s scale, exposure and installation access, from office frontage to industrial property.','A large open site and a sheltered entrance can call for different display arrangements. Share clear site photographs, intended flag sizes and any restrictions around vehicle movements or work areas.'),
('manitoba','Manitoba',['Winnipeg'],'Start with the destination, display requirements and the practical schedule for delivery or field work.','For properties outside a main urban area, include travel and receiving details in the initial request. Seasonal access, surface conditions and work windows should be identified before installation is scheduled.'),
('saskatchewan','Saskatchewan',['Saskatoon','Regina'],'A clear location brief helps distinguish product supply from the access and equipment required for on-site service.','For open grounds, industrial settings and event sites, describe surrounding exposure and the installation surface. Multi-property requests should list each address rather than use one regional location.'),
('nova-scotia','Nova Scotia',['Halifax'],'Coordinate flags and flagpole work around your property, event venue and delivery destination.','Identify exposed waterfront settings, restricted loading areas and site permissions where relevant. For a rental, include both setup and collection windows so logistics can be reviewed together.'),
('new-brunswick','New Brunswick',['Moncton','Fredericton','Saint John'],'Bring together flag requirements, approved artwork and the delivery or service locations in your request.','For bilingual branding or civic displays, provide the approved artwork and flag list. If several facilities are involved, include local contacts and distinguish common product needs from site-specific repairs.'),
('newfoundland-and-labrador','Newfoundland & Labrador',["St. John's"],'Give the exact destination and schedule early, especially when a project involves more than one receiving location.','State whether delivery is to Newfoundland or Labrador and include any onward transport arrangements. For outdoor displays, share site exposure and access details rather than choosing a pole by height alone.'),
('prince-edward-island','Prince Edward Island',['Charlottetown'],'Plan permanent displays and event rentals around the venue, available space and required dates.','For seasonal properties and festivals, include opening dates, setup access and the removal deadline. Confirm who approves temporary placement and whether ground disturbance is permitted.'),
('yukon','Yukon',['Whitehorse'],'Start with a detailed destination and access brief so product and service options can be assessed together.','Include freight receiving arrangements, seasonal access restrictions and site contacts. For replacement work, clear product records and photographs can help establish what is needed before travel is considered.'),
('northwest-territories','Northwest Territories',['Yellowknife'],'A complete project brief is particularly useful when transport and field access need coordination.','List the exact community, receiving arrangements and any onward transport requirements. Share pole details and safe ground-level photographs to help define the work before scheduling is discussed.'),
('nunavut','Nunavut',[],'Identify the community and transport requirements at the start of the request.','Include freight arrangements, a local receiving contact and seasonal timing constraints. Product delivery and on-site service are assessed separately; neither is assumed from a province or territory selection.')]
def slugify(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
CITY_NOTES={
('ontario','toronto'):('Toronto','Plan around the property’s operating rhythm.','Downtown sites may require defined loading windows and coordination with building management. For retail, campuses and commercial grounds, identify pedestrian routes and the work area needed for any equipment.','Office entrances and corporate identity|Condominium and property-management portfolios|Conference, ceremony and festival displays','Mississauga, Brampton and Hamilton'),
('ontario','ottawa'):('Ottawa','Make the display brief as clear as the procurement brief.','For civic, government or institutional work, attach prescribed flag specifications and identify the person who authorizes display instructions. Event requests should include the venue plan and exact setup window.','Institutional entrances and campus displays|Delegation and ceremonial flags|Multi-building replacement planning','Ottawa and surrounding communities'),
('british-columbia','vancouver'):('Vancouver','Separate the display plan from the access plan.','For urban sites, include loading and building-access information. Waterfront and exposed locations need their conditions described when selecting a display. If the request includes an island destination, identify that leg of the delivery separately.','Hospitality and commercial frontage|Temporary event displays|Corporate and institutional flag programs','Surrey and surrounding Lower Mainland communities'),
('alberta','calgary'):('Calgary','Match the display to the scale of the site.','Commercial frontage, open industrial grounds and temporary events have different placement and access needs. Include a site photograph, vehicle routes and the proposed display position so installation scope can be reviewed.','Dealership and industrial displays|Corporate entrances and multi-site accounts|Festival and launch-event rentals','Calgary and surrounding communities'),
('quebec','montreal'):('Montreal','Bring artwork, venue and display guidance together.','Provide approved French or bilingual artwork where required and identify the organization’s display guidance. For events or busy commercial properties, include loading access, setup windows and temporary-placement permissions.','Hotels and corporate properties|Festivals, conferences and film productions|Municipal and institutional displays','Montreal and surrounding communities')}
locbody=hero('LOCATIONS','A Canadian outlook.<br>A site-specific approach.','Explore regional planning details and tell us your destination. Product supply, rentals and on-site service are confirmed for each request.')
locbody+='<section class="wrap section"><label for="location-search" class="eyebrow">FIND A PROVINCE, TERRITORY OR CITY</label><input id="location-search" class="location-filter" type="search" placeholder="Search locations" autocomplete="off"><p id="location-count" role="status" class="small">Explore 13 provinces and territories.</p><div id="location-groups">'
for slug,name,cities,intro,note in REGIONS:
 links=''.join(link('/locations/'+slug+'/'+slugify(c)+'/' if (slug,slugify(c)) in CITY_NOTES else '/locations/'+slug+'/#'+slugify(c),c.upper()) for c in cities)
 locbody+=f'<div class="location-group" data-search="{esc(name+" "+" ".join(cities))}"><h3><a href="/locations/{slug}/">{name}</a></h3><p>{intro}</p><div class="category-links">{links}</div></div>'
 regionbody=hero('LOCATIONS',name+'.',intro)
 regionbody+='<section class="wrap two-column section"><div><h2>Plan for the actual destination.</h2><p>'+note+'</p><p>Tell us what you need and where. Availability, delivery arrangements and any on-site work are reviewed against the location and project scope.</p></div><div><h3>A useful regional request includes</h3><ul class="bullets"><li>City or community and postal code</li><li>Flag types, quantities and display purpose</li><li>Existing pole details or proposed installation photos</li><li>Required dates and site-access constraints</li></ul>'+button('REQUEST A LOCAL QUOTE')+'</div></section>'
 if cities:
  regionbody+='<section class="wrap section">'+section_head('DESTINATIONS','Start with your city.')+'<div class="category-links">'+links+'</div>'
  for c in cities:
   if (slug,slugify(c)) not in CITY_NOTES:
    regionbody+=f'<div id="{slugify(c)}" class="location-group"><h3>{c}</h3><p>For a request in {c}, include your postal code, project type and required dates. Use the regional considerations above to describe access, delivery and display requirements.</p>{link("/quote/?city="+c.replace(' ','%20'),"REQUEST A QUOTE","text-link")}</div>'
  regionbody+='</section>'
 regionbody+='<section class="content-band"><div class="wrap">'+cards([('Flags & custom artwork','/flags/','National, regional and branded displays.'),('Rentals & event displays','/flag-rentals/','Flag, pole and setup requirements for your dates.'),('Installation & service','/services/','A scope based on the actual site and access.')])+'</div></section>'
 add('/locations/'+slug+'/',name+' flags & flagpole planning',intro,regionbody)
locbody+='</div><p id="no-locations" hidden>No matching locations. You can still include your community in a quote request.</p></section>'
add('/locations/','Canadian locations','Explore province, territory and city planning information for flag supply, rentals, installation and service requests.',locbody)
for (region,slug),(city,heading,note,uses,nearby) in CITY_NOTES.items():
 b=hero('LOCAL PLANNING',city+' flags &<br>flagpole solutions.','Plan flags, rentals, installation or service for your '+city+' property or event. On-site availability is confirmed for your address and requirements.')
 b+='<section class="wrap two-column section"><div><h2>'+heading+'</h2><p>'+note+'</p><h3>Nearby destinations</h3><p>If your request also covers '+nearby+', include a separate address and contact for each site. Travel and delivery requirements are reviewed for the full scope.</p></div><div><h3>Applications to plan for</h3><ul class="bullets">'+''.join('<li>'+u+'</li>' for u in uses.split('|'))+'</ul><p>National, international, custom and corporate flags can be specified around the display. Stock, production options and dates are confirmed in the quote.</p></div></section>'
 b+='<section class="content-band"><div class="wrap">'+cards([('Installation','/flagpole-installation/','Share placement, access and existing foundation information.'),('Rentals','/flag-rentals/','Include event dates, venue, quantities and setup needs.'),('Commercial service','/flag-service/','Bring flag replacement and agreed checks into one plan.')])+'</div></section>'
 b+=faq([('Can I visit a local store?','Start your enquiry online or by phone. This page does not list a walk-in showroom or pickup location.'),('Can I request a repair without knowing the pole model?','Yes. Include approximate height, the issue and safely taken ground-level photos. Parts and access requirements can then be reviewed.'),('Is installation available for my address?','Provide the address or postal code and required work. On-site arrangements depend on regional availability, site access and the project requirements.')])
 add('/locations/'+region+'/'+slug+'/',city+' flags & flagpole solutions','Local planning for '+city+' flags, custom flags, rentals, installation, repairs and commercial flag service.',b)
resources=[('choosing-a-flagpole','Choosing a flagpole','Start with the site, not just the height.'),('flag-care','Looking after your flags','Recognize wear and plan useful replacements.'),('flag-etiquette','Canadian flag etiquette','Find the official guidance for your display.'),('rental-planning','Planning an event flag rental','Bring dates, venue and display details together.')]
add('/resources/','Flag & flagpole resources','Practical guides to selecting flagpoles, caring for flags, event rentals and official Canadian flag etiquette.',hero('RESOURCES','A little knowledge.<br>A better brief.','Practical information to help you choose, plan and look after your display.','hardware')+'<section class="wrap section">'+cards([(t,'/resources/'+s+'/',d) for s,t,d in resources])+'</section>')
add('/resources/choosing-a-flagpole/','Choosing a flagpole','Compare flagpole materials, operating systems and mounting approaches.',hero('THE WAVING GUIDE','Choose around<br>the whole setting.','Flag size, site exposure, mounting and maintenance access matter alongside appearance.','hardware')+'<section class="wrap section"><div class="table-scroll"><table><thead><tr><th>Choice</th><th>What it means</th><th>What to confirm</th></tr></thead><tbody><tr><td>Internal halyard</td><td>The raising mechanism runs inside the pole.</td><td>Operating access, security and maintenance requirements.</td></tr><tr><td>External halyard</td><td>The rope runs outside the pole.</td><td>Cleat access, rope condition and attachment compatibility.</td></tr><tr><td>Permanent ground-mounted</td><td>A fixed display position.</td><td>Site conditions, foundation requirements and access.</td></tr><tr><td>Portable or temporary</td><td>A display for changing locations or limited dates.</td><td>Surface, base compatibility, exposure and venue permissions.</td></tr></tbody></table></div><p>Product-specific specifications and site requirements determine suitability. No material or operating system is automatically right for every location.</p></section>')
add('/resources/flag-care/','Flag care & replacement planning','Recognize visible flag wear and prepare a useful replacement or maintenance request.',hero('THE WAVING GUIDE','Keep an eye<br>on the details.','A routine look from ground level can help you spot a flag that needs attention.','hardware')+'<article class="wrap prose"><h2>Look for visible wear.</h2><p>Note frayed edges, tears, faded colours, detached clips or a flag that no longer moves as expected. Describe what you can see without climbing or reaching into the operating system.</p><h2>Match the replacement to the display.</h2><p>Record the existing design, dimensions and attachment style if known. Keep approved brand artwork available for custom flags and note any differences between sites.</p><h2>Plan around the property.</h2><p>Replacement intervals vary with exposure, fabric, use and condition. An agreed inspection schedule can help a property team decide when replacement is appropriate.</p><h2>Leave damaged systems alone.</h2><p>Do not force a jammed rope or approach loose overhead components. Describe the issue and ask for an appropriate assessment.</p>'+button('REQUEST FLAG REPLACEMENT','Flag%20Replacement')+'</article>')
add('/resources/flag-etiquette/','Canadian flag etiquette resources','Official Canadian Heritage resources for displaying the National Flag and half-masting.',hero('THE WAVING GUIDE','Give the display<br>the right consideration.','Use current official guidance and your organization’s applicable policy when planning a flag arrangement.')+'<article class="wrap prose"><h2>Start with official guidance.</h2><p>Canadian Heritage provides guidance on displaying the National Flag, including arrangements with other flags. Check the guidance relevant to the display you are planning.</p><p><a href="https://www.canada.ca/en/canadian-heritage/services/flag-canada-etiquette.html">National Flag of Canada etiquette</a></p><h2>Confirm who authorizes changes.</h2><p>For half-masting, identify the responsible person and the instructions that apply to your organization. Federal rules describe the federal context; they should not be assumed to replace every organization’s policy.</p><p><a href="https://www.canada.ca/en/canadian-heritage/services/flag-canada-masting-rules.html">Rules for half-masting the National Flag of Canada</a></p><h2>Ask before reproducing a design.</h2><p>Use approved artwork and obtain any permissions needed for organizational, municipal, Indigenous or other protected designs.</p></article>')
add('/resources/rental-planning/','Event flag rental planning','Prepare a flag rental brief with dates, venue access, flag quantities and installation requirements.',hero('THE WAVING GUIDE','The event starts<br>with a clear plan.','A little information early helps define the display and its logistics.','event')+'<section class="wrap section">'+steps([('Count the full rental period','Include setup, rehearsals, event days and collection—not only the main event.'),('Describe the venue','Identify indoor or outdoor use, surface, circulation and permissions.'),('List the display','Specify designs, quantities, poles, bases and any custom artwork.'),('Agree the logistics','Request delivery, installation and collection where needed.')])+'<p>Share any venue rules and weather-related operating requirements with your request. Do not assume a temporary setup is suitable for every surface or condition.</p></section>')
add('/about/','About Waving','Flags, flagpoles, rentals, installation and ongoing care for Canadian properties and organizations.',hero('ABOUT WAVING','A flag is a small detail.<br>With a big presence.','Waving brings flags, flagpoles, rentals and service together for the places where people work, gather and belong.')+split('KEEP CANADA WAVING','From the first flag<br>to the next replacement.','Our focus is practical: the right display for the setting, a clear quote and a plan for the work involved. Commercial properties, institutions, events and homes each have their own requirements. That is where the conversation starts.','event','Flags arranged in an outdoor gathering space')+'<section class="wrap section">'+cards([('Consider the setting','/flagpoles/','Choose around the property, exposure and how the flag is used.'),('Make the brief clear','/quote/','Bring product, location and service requirements into one request.'),('Think beyond installation','/flag-service/','Plan replacement and care alongside the display itself.')])+'</section>')
add('/contact/','Contact Waving','Discuss flags, flagpoles, rentals, installation or commercial service with Waving.',hero('CONTACT','Tell us what<br>you have in mind.','One flag, an upcoming event, a repair or an entire portfolio. Start with the details you know.')+'<section class="wrap two-column section"><div><h2>Start a quote.</h2><p>Use our short form to tell us what you need and how to reach you. Photos and artwork are optional.</p>'+button('GET A QUOTE')+'</div><div><h2>Prefer to talk?</h2><p><a class="phone" href="tel:+18336969996">(833) 696-9996</a></p><p>Have your city, project type and required dates ready. Availability and scope are confirmed for each request.</p></div></section>')
add('/privacy/','Privacy','How the Waving website handles quote information and contact details.','<article class="wrap prose"><p class="eyebrow">YOUR INFORMATION</p><h1>Privacy.</h1><p>This website asks only for information relevant to a flag, flagpole, rental or service enquiry.</p><h2>Information you choose to provide</h2><p>A quote request may include your name, business, contact details, general location, project requirements and optional files. Do not include payment-card details, identity documents or other sensitive personal information. Only upload files you have permission to share.</p><h2>How the form works</h2><p>Information entered in the quote form stays in the current page until you submit it. It is not saved to browser storage. Refreshing or closing the page may remove the entries. If a submission fails, entries remain available in the open form.</p><h2>Use of enquiry information</h2><p>Enquiry details are intended to assess the request and coordinate a response. Submitting an enquiry is not consent to unrelated marketing. A service-accepted submission confirms receipt by the form service, not delivery to a particular inbox.</p><h2>Hosting and technical information</h2><p>The website is hosted through OpenAI Sites. Hosting providers may process technical request information to operate and protect the service. This site does not add advertising trackers or browser-storage analytics. Anonymous interaction events are available to the page, but no external analytics collector is configured.</p><h2>Your choices</h2><p>Provide only the project details needed for an initial discussion. You may request correction or deletion of enquiry information by contacting Waving at <a href="tel:+18336969996">(833) 696-9996</a>. File uploads and message delivery depend on the configured enquiry service.</p></article>')
add('/accessibility/','Accessibility','Accessibility features and contact options for the Waving website.','<article class="wrap prose"><p class="eyebrow">ACCESSIBILITY</p><h1>A useful website<br>for more people.</h1><p>The site supports keyboard navigation, visible focus indicators, labelled form fields and a single-page quote form. Motion respects your device’s reduced-motion preference.</p><h2>If something gets in your way</h2><p>Call <a href="tel:+18336969996">(833) 696-9996</a> to discuss your request. If reporting a website issue, include the page and what you were trying to do.</p></article>')
add('/404/','Page not found','The requested page could not be found.','<section class="wrap prose"><p class="eyebrow">404</p><h1>This page isn’t here.</h1><p>Find a product or service from the navigation, or return to the homepage.</p><a class="button" href="/">BACK TO HOME</a></section>')
quote='''<section class="wrap quote-layout"><aside class="quote-aside"><p class="eyebrow">LET’S GET THE DETAILS RIGHT</p><h1>Your next flag<br>starts here.</h1><p>Tell us what you need. We’ll help shape the right request.</p><p class="small">No need to know every specification.<br>Share what you have and add useful photos.</p><p>Prefer to talk?<br><a href="tel:+18336969996">(833) 696-9996</a></p></aside><div class="quote-panel"><noscript><h2>Let’s talk through your request.</h2><p>The quote form needs JavaScript. Call <a href="tel:+18336969996">(833) 696-9996</a> and have your city, project type and dates ready.</p></noscript><form id="quote-form" novalidate hidden><div id="form-error" class="error" role="alert" hidden></div><div id="step-content"></div><div class="form-actions"><button type="button" id="previous" class="button outline" hidden>BACK</button><button type="button" id="next" class="button">REQUEST MY QUOTE</button></div><div style="position:absolute;left:-10000px" aria-hidden="true"><label>Leave this field empty<input name="_gotcha" tabindex="-1" autocomplete="off"></label></div></form><div id="quote-success" role="status" hidden><p class="eyebrow">REQUEST ACCEPTED</p><h2>Thank you for the details.</h2><p>Your request has been accepted by the enquiry service. This confirms submission; it does not confirm delivery to a particular inbox.</p><a class="button navy" href="/">BACK TO HOME</a></div></div></section><script src="/assets/config.js"></script><script defer src="/assets/quote.js"></script>'''
add('/quote/','Request a quote','Request flags, custom flags, flagpoles, rentals, installation, repairs or commercial flag service with a guided quote form.',quote)

